// Managed file - regenerated by `aic script workspace update`.
//
// ESLint rule for static `openidm.query("managed/<object>", {
// _queryFilter: "..." })` calls. It validates field names against the
// tenant-specific managed schema snapshot generated beside the `.d.ts` files.

import { readFileSync } from "node:fs";

const QUERY_OPERATORS = new Set([
  "eq",
  "ne",
  "co",
  "sw",
  "lt",
  "le",
  "gt",
  "ge",
  "pr",
  "in",
]);
const QUERY_KEYWORDS = new Set(["and", "or", "not", "true", "false", "null"]);

export function loadManagedQueryFields(url) {
  try {
    return JSON.parse(readFileSync(url, "utf8"));
  } catch (error) {
    if (error && (error.code === "ENOENT" || error.code === "ENOTDIR")) {
      return {};
    }
    throw error;
  }
}

function propertyName(node) {
  if (!node) return null;
  if (node.type === "Identifier") return node.name;
  if (node.type === "Literal" && typeof node.value === "string") return node.value;
  return null;
}

function staticString(node) {
  if (!node) return null;
  if (node.type === "Literal" && typeof node.value === "string") return node.value;
  if (node.type === "TemplateLiteral" && node.expressions.length === 0) {
    return node.quasis.map((quasi) => quasi.value.cooked).join("");
  }
  return null;
}

function staticStringRange(sourceCode, node) {
  const value = staticString(node);
  if (value === null || !node.range) return null;
  if (node.type === "Literal") {
    return {
      value: sourceCode.getText(node).slice(1, -1),
      start: node.range[0] + 1,
      end: node.range[1] - 1,
    };
  }
  if (node.type === "TemplateLiteral" && node.expressions.length === 0) {
    const quasi = node.quasis[0];
    return {
      value: sourceCode.getText(node).slice(1, -1),
      start: quasi.range[0] + 1,
      end: quasi.range[1] - 1,
    };
  }
  return null;
}

function isOpenidmQuery(node) {
  if (!node || node.type !== "MemberExpression" || node.computed) return false;
  return (
    node.object &&
    node.object.type === "Identifier" &&
    node.object.name === "openidm" &&
    propertyName(node.property) === "query"
  );
}

function queryFilterProperty(paramsNode) {
  if (!paramsNode || paramsNode.type !== "ObjectExpression") return null;
  for (const property of paramsNode.properties) {
    if (property.type !== "Property") continue;
    if (propertyName(property.key) === "_queryFilter") return property.value;
  }
  return null;
}

function tokenizeQueryFilter(filter) {
  const tokens = [];
  let i = 0;

  while (i < filter.length) {
    const ch = filter[i];
    if (/\s/.test(ch)) {
      i++;
      continue;
    }
    if (ch === '"' || ch === "'") {
      const quote = ch;
      const start = i;
      i++;
      while (i < filter.length) {
        if (filter[i] === "\\") {
          i += 2;
          continue;
        }
        if (filter[i] === quote) {
          i++;
          break;
        }
        i++;
      }
      tokens.push({ type: "string", start, end: i });
      continue;
    }
    if ("()[],".includes(ch)) {
      tokens.push({ type: "punct", value: ch, start: i, end: i + 1 });
      i++;
      continue;
    }

    const start = i;
    while (
      i < filter.length &&
      !/\s/.test(filter[i]) &&
      !'"\'()[],'.includes(filter[i])
    ) {
      i++;
    }
    tokens.push({ type: "word", value: filter.slice(start, i), start, end: i });
  }

  return tokens;
}

function isFieldWord(token) {
  if (!token || token.type !== "word") return false;
  const lower = token.value.toLowerCase();
  if (QUERY_OPERATORS.has(lower) || QUERY_KEYWORDS.has(lower)) return false;
  return !/^-?\d+(?:\.\d+)?$/.test(token.value);
}

export function extractQueryFilterFields(filter) {
  const tokens = tokenizeQueryFilter(filter);
  const fields = [];

  for (let i = 0; i < tokens.length - 1; i++) {
    const token = tokens[i];
    const next = tokens[i + 1];
    if (!isFieldWord(token) || next.type !== "word") continue;
    if (QUERY_OPERATORS.has(next.value.toLowerCase())) {
      fields.push(token.value);
    }
  }

  return fields;
}

function suggestionFor(root, knownFields) {
  const candidates = knownFields.filter((candidate) => candidate !== root);
  let best = null;

  for (const candidate of candidates) {
    const distance = levenshtein(root, candidate);
    if (distance <= 2 && (!best || distance < best.distance)) {
      best = { candidate, distance };
    }
  }

  return best ? best.candidate : null;
}

function queryFieldRoot(field) {
  // AIC's web console may serialize CREST query fields with a leading slash
  // (`/_id eq "..."`). The server accepts both `_id` and `/_id`; treat the
  // slash form as a JSON-pointer-like spelling of the same field path.
  return field.replace(/^\/+/, "").split("/")[0];
}

function queryFieldRootEnd(field) {
  const leading = field.match(/^\/*/)[0].length;
  const remainder = field.slice(leading);
  const slash = remainder.indexOf("/");
  return leading + (slash === -1 ? remainder.length : slash);
}

function levenshtein(left, right) {
  const previous = Array.from({ length: right.length + 1 }, (_, i) => i);
  const current = Array.from({ length: right.length + 1 }, () => 0);

  for (let i = 1; i <= left.length; i++) {
    current[0] = i;
    for (let j = 1; j <= right.length; j++) {
      const cost = left[i - 1] === right[j - 1] ? 0 : 1;
      current[j] = Math.min(
        previous[j] + 1,
        current[j - 1] + 1,
        previous[j - 1] + cost
      );
    }
    for (let j = 0; j < previous.length; j++) {
      previous[j] = current[j];
    }
  }

  return previous[right.length];
}

export function validateQueryFilterFields(filter, knownFields) {
  const known = new Set(knownFields);
  const issues = [];
  const tokens = tokenizeQueryFilter(filter);

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (!isFieldWord(token)) continue;

    const next = tokens[i + 1];
    if (!next || next.type !== "word") continue;

    const nextLower = next.value.toLowerCase();
    if (!QUERY_OPERATORS.has(nextLower)) {
      if (!QUERY_KEYWORDS.has(nextLower)) {
        issues.push({
          kind: "operator",
          operator: next.value,
          start: next.start,
          end: next.end,
        });
      }
      continue;
    }

    const root = queryFieldRoot(token.value);
    if (!known.has(root)) {
      const rootEnd = queryFieldRootEnd(token.value);
      issues.push({
        kind: "field",
        field: token.value,
        root,
        start: token.start,
        end: token.start + rootEnd,
        suggestion: suggestionFor(root, knownFields),
      });
    }
  }

  return issues;
}

function locFromIndex(sourceCode, stringRange, relativeIndex) {
  return sourceCode.getLocFromIndex(stringRange.start + relativeIndex);
}

function rangeFromIssue(stringRange, issue) {
  return [stringRange.start + issue.start, stringRange.start + issue.end];
}

function replacementForField(field, suggestion) {
  const leadingSlash = field.startsWith("/") ? "/" : "";
  return `${leadingSlash}${suggestion}`;
}

export function openidmQueryFilterRule(managedFields) {
  return {
    meta: {
      type: "problem",
      docs: {
        description:
          "validate literal openidm.query _queryFilter fields against generated managed-object schema fields",
      },
      hasSuggestions: true,
      schema: [],
    },
    create(context) {
      const sourceCode = context.sourceCode || context.getSourceCode();
      return {
        CallExpression(node) {
          if (!isOpenidmQuery(node.callee)) return;

          const resource = staticString(node.arguments[0]);
          if (
            !resource ||
            !Object.prototype.hasOwnProperty.call(managedFields, resource)
          ) {
            return;
          }

          const queryFilterNode = queryFilterProperty(node.arguments[1]);
          const queryFilter = staticStringRange(sourceCode, queryFilterNode);
          if (!queryFilter) return;

          const knownFields = managedFields[resource];
          const issues = validateQueryFilterFields(queryFilter.value, knownFields);
          for (const issue of issues) {
            const range = rangeFromIssue(queryFilter, issue);
            const loc = {
              start: locFromIndex(sourceCode, queryFilter, issue.start),
              end: locFromIndex(sourceCode, queryFilter, issue.end),
            };
            if (issue.kind === "operator") {
              context.report({
                node: queryFilterNode,
                loc,
                message:
                  "Unknown _queryFilter operator '{{operator}}'. Expected one of: eq, ne, co, sw, lt, le, gt, ge, pr, in.",
                data: {
                  operator: issue.operator,
                },
              });
              continue;
            }

            context.report({
              node: queryFilterNode,
              loc,
              message: issue.suggestion
                ? "Unknown _queryFilter field '{{field}}' for {{resource}}. Did you mean '{{suggestion}}'?"
                : "Unknown _queryFilter field '{{field}}' for {{resource}}.",
              data: {
                field: issue.field,
                resource,
                suggestion: issue.suggestion,
              },
              suggest: issue.suggestion
                ? [
                    {
                      desc: `Replace with '${replacementForField(
                        issue.field,
                        issue.suggestion
                      )}'`,
                      fix(fixer) {
                        return fixer.replaceTextRange(
                          range,
                          replacementForField(issue.field, issue.suggestion)
                        );
                      },
                    },
                  ]
                : [],
            });
          }
        },
      };
    },
  };
}
